import { createStorageClient } from './client.js';
import { getGenerateUploadInstructions } from './client-uploads/generate.js';
import { getCopyFile } from './copyFile.js';
import { getDeleteFile } from './deleteFile.js';
import { getGenerateURL } from './generateURL.js';
import { getHandleUpload } from './handleUpload.js';
import { getHandler } from './staticHandler.js';
export function contentApiStorageAdapter(config) {
    return ({ collection, prefix })=>{
        const client = createStorageClient(config);
        const baseUrl = config.baseUrl;
        const deleteFile = getDeleteFile({
            client
        });
        return {
            name: 'content-api',
            copyFile: getCopyFile({
                client
            }),
            deleteFile,
            generateURL: getGenerateURL({
                baseUrl
            }),
            handleDelete: deleteFile,
            handleUpload: getHandleUpload({
                client,
                collection
            }),
            staticHandler: getHandler({
                client,
                collection,
                prefix
            }),
            uploadInstructions: {
                enabled: true,
                generate: getGenerateUploadInstructions({
                    access: config.uploadInstructionsAccess,
                    client,
                    collectionPrefix: prefix
                }),
                requiresUploadReceipt: true,
                useInAdmin: true
            }
        };
    };
}
